package local.hyperceiler.ambientcolorprobe;
import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.content.*;import android.widget.TextView;import dalvik.system.DexClassLoader;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
public class MainActivity extends Activity {
 private final JSONArray rows=new JSONArray(),frames=new JSONArray(); private int failures; private ClassLoader ota;private File dir;private Class<?> media,palette;private Object resolver;
 interface Task{void run()throws Exception;}
 void check(String n,boolean b)throws Exception{rows.put(new JSONObject().put("name",n).put("passed",b));if(!b)failures++;}
 void test(String n,Task t){try{t.run();}catch(Throwable x){try{StringWriter w=new StringWriter();x.printStackTrace(new PrintWriter(w));rows.put(new JSONObject().put("name",n).put("passed",false).put("exception",w.toString()));failures++;}catch(Exception bad){throw new RuntimeException(bad);}}}
 public void onCreate(Bundle b){super.onCreate(b);TextView v=new TextView(this);v.setText("Running exact OTA color dependency probe; no phone verification");setContentView(v);dir=new File(getFilesDir(),"run");dir.mkdirs();new Thread(this::execute,"ota-color-probe").start();}
 Object resolve(Object data,boolean optimized)throws Exception{return resolver.getClass().getMethod("resolve",Context.class,Object.class,boolean.class).invoke(resolver,this,data,optimized);}
 int light(Object c)throws Exception{return (Integer)c.getClass().getMethod("getLight").invoke(c);}
 int dark(Object c)throws Exception{return (Integer)c.getClass().getMethod("getDark").invoke(c);}
 Object media(Icon icon)throws Exception{Constructor<?> found=null;for(Constructor<?> c:media.getDeclaredConstructors())if(c.getParameterCount()==32)found=c; if(found==null)throw new IllegalStateException("full MediaData constructor not found: "+Arrays.toString(media.getDeclaredConstructors()));Class<?>[] t=found.getParameterTypes();Object[] a=new Object[t.length];for(int i=0;i<t.length;i++){if(t[i]==int.class)a[i]=0;else if(t[i]==long.class)a[i]=0L;else if(t[i]==boolean.class)a[i]=false;else if(t[i]==List.class)a[i]=Collections.emptyList();else if(t[i]==String.class)a[i]="probe";}a[6]=icon;a[10]=getPackageName();return found.newInstance(a);}
 Bitmap bitmap(int a,int b){Bitmap x=Bitmap.createBitmap(64,48,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(x);c.drawColor(a);Paint p=new Paint();p.setColor(b);c.drawRect(16,12,48,36,p);return x;}
 void save(String name,Drawable d)throws Exception{Bitmap x=Bitmap.createBitmap(96,96,Bitmap.Config.ARGB_8888);d.setBounds(0,0,96,96);d.draw(new Canvas(x));try(FileOutputStream f=new FileOutputStream(new File(dir,name+".png"))){x.compress(Bitmap.CompressFormat.PNG,100,f);}frames.put(name+".png");}
 Object privateDrawable(Drawable d)throws Exception{Method m=resolver.getClass().getDeclaredMethod("privateDrawable",Context.class,Drawable.class,int.class);m.setAccessible(true);return m.invoke(resolver,this,d,0);}
 Object privateColors(String name,Drawable d)throws Exception{Method m=resolver.getClass().getDeclaredMethod(name,Drawable.class);m.setAccessible(true);return m.invoke(resolver,d);}
 List<?> shades(Bitmap b)throws Exception{Class<?> c=Class.forName("com.android.systemui.monet.ColorScheme",true,ota);Object scheme=c.getConstructor(WallpaperColors.class,boolean.class,int.class).newInstance(WallpaperColors.fromBitmap(b),true,6);Object accent=c.getField("mAccent1").get(scheme);return(List<?>)accent.getClass().getField("allShades").get(accent);}
 void execute(){
  test("exact OTA DEX loader",()->{File apk=new File(getFilesDir(),"ota-systemui.apk");if(apk.exists())apk.delete();try(InputStream in=getAssets().open("ota-systemui.apk");FileOutputStream out=new FileOutputStream(apk)){apk.setReadOnly();byte[] buf=new byte[65536];for(int n;(n=in.read(buf))!=-1;)out.write(buf,0,n);}File original=new File(getFilesDir(),"libMiMainColor.so");try(InputStream in=new FileInputStream(new File(getApplicationInfo().nativeLibraryDir,"libMiMainColor.so"));FileOutputStream out=new FileOutputStream(original)){byte[] buf=new byte[65536];for(int n;(n=in.read(buf))!=-1;)out.write(buf,0,n);}boolean single=getIntent().getBooleanExtra("single_loader",false);String dexPath=single?getApplicationInfo().sourceDir+File.pathSeparator+apk:apk.toString();ota=new DexClassLoader(dexPath,getCodeCacheDir().toString(),getFilesDir().toString()+File.pathSeparator+getApplicationInfo().nativeLibraryDir,single?getClassLoader().getParent():getClassLoader());media=Class.forName("com.android.systemui.media.controls.shared.model.MediaData",false,ota);palette=Class.forName("miuix.mipalette.MiPalette",false,ota);Class<?> resolverType=Class.forName("com.sevtinge.hyperceiler.libhook.rules.systemui.controlcenter.media3.AmbientColorResolverOS4",true,single?ota:getClassLoader());Object companion=resolverType.getField("Companion").get(null);resolver=companion.getClass().getMethod("create",ClassLoader.class,boolean.class,boolean.class).invoke(companion,ota,true,true);check("resolver uses selected defining loader",resolverType.getClassLoader()==(single?ota:getClassLoader()));check("complete actual dependency shape resolves",resolver!=null);check("MediaData loaded from child OTA loader",media.getClassLoader()==ota);check("palette loaded from child OTA loader",palette.getClassLoader()==ota);});
  test("constructor arity",()->{for(Constructor<?> c:media.getDeclaredConstructors())rows.put(new JSONObject().put("name","actual MediaData constructor "+c.getParameterCount()).put("passed",true).put("signature",c.toString()));});
  if(getIntent().getBooleanExtra("oem_media_init",false))test("actual ROM media init precondition",()->{palette.getMethod("init").invoke(null);check("complete original MiPalette.init() called before paired samples",true);});
  int[][] colors={{Color.RED,Color.BLUE},{Color.GREEN,Color.YELLOW},{Color.DKGRAY,Color.LTGRAY},{Color.TRANSPARENT,Color.TRANSPARENT}};
  for(int i=0;i<colors.length;i++){final int k=i;test("actual standard serial "+k,()->{Bitmap b=bitmap(colors[k][0],colors[k][1]);int original=(Integer)palette.getMethod("getMainColorHCT",Bitmap.class).invoke(null,b);Object md=media(Icon.createWithBitmap(b));Object q=resolve(md,false);check("private Java sampling equals actual serial original "+k,q!=null&&light(q)==original&&dark(q)==original);check("borrowed bitmap remains live "+k,!b.isRecycled());rows.put(new JSONObject().put("name","actual HCT color "+k).put("passed",true).put("original_argb",original).put("isolated_light",q==null?JSONObject.NULL:light(q)).put("isolated_dark",q==null?JSONObject.NULL:dark(q)));});
   test("actual optimized palette "+k,()->{Bitmap b=bitmap(colors[k][0],colors[k][1]);List<?> values=shades(b);Object q=resolve(media(Icon.createWithBitmap(b)),true);check("actual Monet thirteen shades "+k,values.size()==13);check("production actual Monet selected indices "+k,q!=null&&Objects.equals(light(q),values.get(4))&&Objects.equals(dark(q),values.get(7)));});
  }
  test("actual adaptive privately rendered",()->{AdaptiveIconDrawable original=new AdaptiveIconDrawable(new ColorDrawable(Color.RED),new ColorDrawable(0x660000ff));Drawable copy=(Drawable)privateDrawable(original);check("adaptive privately copied",copy!=null&&copy!=original);save("adaptive-private",copy);check("adaptive original bounds untouched",original.getBounds().isEmpty());check("adaptive standard color produced",privateColors("standardColors",copy)!=null);check("adaptive optimized color produced",privateColors("optimizedColors",copy)!=null);});
  test("actual dimensionless ColorDrawable",()->{Drawable original=new ColorDrawable(Color.CYAN);check("ColorDrawable has no intrinsic size",original.getIntrinsicWidth()<=0&&original.getIntrinsicHeight()<=0);Drawable copy=(Drawable)privateDrawable(original);check("dimensionless ColorDrawable private",copy!=null&&copy!=original);check("dimensionless ColorDrawable standard",privateColors("standardColors",copy)!=null);check("dimensionless ColorDrawable optimized",privateColors("optimizedColors",copy)!=null);check("dimensionless original bounds preserved",original.getBounds().isEmpty());});
  test("actual dimensionless ShapeDrawable",()->{ShapeDrawable original=new ShapeDrawable(new android.graphics.drawable.shapes.OvalShape());original.getPaint().setColor(Color.MAGENTA);check("ShapeDrawable has no intrinsic size",original.getIntrinsicWidth()<=0&&original.getIntrinsicHeight()<=0);Drawable copy=(Drawable)privateDrawable(original);check("dimensionless ShapeDrawable private",copy!=null&&copy!=original);check("dimensionless ShapeDrawable standard",privateColors("standardColors",copy)!=null);check("dimensionless ShapeDrawable optimized",privateColors("optimizedColors",copy)!=null);check("shape original bounds preserved",original.getBounds().isEmpty());});
  test("actual hardware bitmap ownership",()->{Bitmap software=bitmap(Color.RED,Color.BLUE);Bitmap hardware=software.copy(Bitmap.Config.HARDWARE,false);check("actual hardware bitmap created",hardware!=null&&hardware.getConfig()==Bitmap.Config.HARDWARE);Object q=resolve(media(Icon.createWithBitmap(hardware)),false);check("hardware album standard available",q!=null);check("hardware album optimized available",resolve(media(Icon.createWithBitmap(hardware)),true)!=null);check("hardware input never recycled",!hardware.isRecycled());});
  test("actual Fancy quiet getter/private snapshot",()->{Class<?> f=Class.forName("com.miui.maml.FancyDrawable",false,ota);Object unsafe=Class.forName("sun.misc.Unsafe").getDeclaredMethod("getUnsafe").invoke(null);Object fancy=unsafe.getClass().getMethod("allocateInstance",Class.class).invoke(unsafe,f);Field quiet=f.getDeclaredField("mQuietDrawable");quiet.setAccessible(true);Bitmap b=bitmap(Color.CYAN,Color.MAGENTA);quiet.set(fancy,new BitmapDrawable(getResources(),b));Drawable copy=(Drawable)privateDrawable((Drawable)fancy);check("actual Fancy getter snapshot avoids uninitialized renderer",copy instanceof BitmapDrawable);save("fancy-quiet-private",copy);check("Fancy static optimized color produced",privateColors("optimizedColors",copy)!=null);check("Fancy static standard color produced",privateColors("standardColors",copy)!=null);});
  test("actual app fallback availability",()->{Object q=resolve(media(null),true);check("actual NotificationUtil application icon result",q!=null);});
  try{JSONObject report=new JSONObject().put("oem_media_init",getIntent().getBooleanExtra("oem_media_init",false)).put("single_color_loader",getIntent().getBooleanExtra("single_loader",false)).put("passed",failures==0).put("checks",rows).put("check_count",rows.length()).put("failures",failures).put("frames",frames).put("source_sha256",BuildMetadata.SOURCE_SHA).put("ota_sha256",BuildMetadata.OTA_SHA).put("native_sha256",BuildMetadata.NATIVE_SHA).put("wrapper_sha256",BuildMetadata.WRAPPER_SHA).put("bridge_sha256",BuildMetadata.BRIDGE_SHA).put("device_status","NOT_TESTED").put("scope","Real API37 emulator graphics/ART, complete unmodified OTA DEX classes and original ARM MiMainColor via nativebridge, serial original/production-isolated standard comparison; private bridge differs only by fixed test path. Selectable ordinary-app parent/child or one child loader control; no loader namespace bypass or SystemUI namespace proof. Fancy object allocation bypasses constructor solely to feed an actual quiet getter; no live renderer or work-profile/phone proof. No native-concurrency approval from this resolver probe; separate bridge evidence required.");try(FileOutputStream out=new FileOutputStream(new File(dir,"report.json"))){out.write(report.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}}catch(Exception e){android.util.Log.e("AmbientColorProbe","write report",e);}
 }
}
